import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.DQbZ8cc1.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/introduction.md","filePath":"docs/introduction.md"}'),o={name:"docs/introduction.md"};function l(n,e,s,c,d,h){return i(),r("div",null,[...e[0]||(e[0]=[t('<h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to “Project Overview”">​</a></h2><p>BBS-GO is a lightweight self-hosted community platform for forums, Q&amp;A, and knowledge sharing. It combines forum discussions, Q&amp;A workflows, knowledge articles, moderation, notifications, and member engagement in one Go + React application.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h3><ul><li><strong>Lightweight</strong>: Low resource usage and simple deployment</li><li><strong>Forum + Q&amp;A + Articles</strong>: Supports discussions, answer-focused topics, and reusable knowledge articles</li><li><strong>Unified Release</strong>: One deployment package runs the Go API and bundled React web/dashboard experience</li><li><strong>Self-Hosted</strong>: Keep data and operations under your own control</li><li><strong>Cross-Platform</strong>: Works on Windows, Linux, and macOS</li></ul><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to “Design Principles”">​</a></h3><ul><li><strong>Keep It Simple</strong>: Reduce unnecessary complexity and keep UX clear</li><li><strong>Customizable</strong>: Clean structure for secondary development</li><li><strong>Security First</strong>: Follow security best practices to protect user data</li><li><strong>Go-Powered</strong>: Fast compilation and stable runtime performance</li><li><strong>Responsive by Default</strong>: Consistent experience across desktop and mobile</li><li><strong>Community-Driven</strong>: Iterates quickly through open-source collaboration</li></ul><h3 id="online-links" tabindex="-1">Online Links <a class="header-anchor" href="#online-links" aria-label="Permalink to “Online Links”">​</a></h3><ul><li>Official website: <a href="https://bbs-go.com" target="_blank" rel="noreferrer">https://bbs-go.com</a></li><li>Demo site: <a href="https://bbs.bbs-go.com" target="_blank" rel="noreferrer">https://bbs.bbs-go.com</a></li><li>Feedback: <a href="https://bbs.bbs-go.com/topic/create?nodeId=6" target="_blank" rel="noreferrer">https://bbs.bbs-go.com/topic/create?nodeId=6</a></li><li>Feature requests: <a href="https://bbs.bbs-go.com/topic/609" target="_blank" rel="noreferrer">https://bbs.bbs-go.com/topic/609</a></li></ul><h3 id="source-code" tabindex="-1">Source Code <a class="header-anchor" href="#source-code" aria-label="Permalink to “Source Code”">​</a></h3><ul><li>GitHub: <a href="https://github.com/mlogclub/bbs-go" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go</a></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><h3 id="system-modules" tabindex="-1">System Modules <a class="header-anchor" href="#system-modules" aria-label="Permalink to “System Modules”">​</a></h3><p>BBS-GO is released as an all-in-one deployment package:</p><ul><li><strong>server</strong>: Go backend API, installation flow, configuration, and static resource handling</li><li><strong>web</strong>: React Router frontend and <code>/dashboard</code> admin experience, built into the release package</li></ul><p><img src="https://bbs--go.oss-cn-hangzhou.aliyuncs.com/images/2025/03/11/8754103189670afe659f88d5596c8f2a.png" alt="bbs-go architecture"></p><h3 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to “Tech Stack”">​</a></h3><h4 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to “Backend”">​</a></h4><ul><li><strong>Go</strong> (<a href="https://go.dev" target="_blank" rel="noreferrer">https://go.dev</a>)</li><li><strong>MySQL</strong> (<a href="https://www.mysql.com" target="_blank" rel="noreferrer">https://www.mysql.com</a>)</li><li><strong>Iris</strong> (<a href="https://github.com/kataras/iris" target="_blank" rel="noreferrer">https://github.com/kataras/iris</a>)</li><li><strong>GORM</strong> (<a href="https://gorm.io" target="_blank" rel="noreferrer">https://gorm.io</a>)</li></ul><h4 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to “Frontend”">​</a></h4><ul><li>React + React Router frontend</li><li>Dashboard is part of the same <code>web/</code> application and is served under <code>/dashboard</code></li></ul><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to “Core Capabilities”">​</a></h2><h3 id="user-system" tabindex="-1">User System <a class="header-anchor" href="#user-system" aria-label="Permalink to “User System”">​</a></h3><ul><li>Registration and login</li><li>Third-party login integration</li><li>Permission and role control</li><li>User center</li></ul><h3 id="content-system" tabindex="-1">Content System <a class="header-anchor" href="#content-system" aria-label="Permalink to “Content System”">​</a></h3><ul><li>Topic, Q&amp;A, and article publishing</li><li>Comments and replies</li><li>Tags, nodes, and categorization</li><li>Content moderation and reports</li></ul><h3 id="q-a-and-community-interaction" tabindex="-1">Q&amp;A and Community Interaction <a class="header-anchor" href="#q-a-and-community-interaction" aria-label="Permalink to “Q&amp;A and Community Interaction”">​</a></h3><ul><li>Follow system</li><li>Notifications</li><li>Like and favorite</li><li>Solved/unsolved and accepted-answer workflows</li><li>Growth, points, levels, tasks, and badges</li></ul><h3 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to “Administration”">​</a></h3><ul><li>Content management</li><li>User management</li><li>System settings</li><li>Operational overview and audit logs</li></ul><h2 id="project-highlights" tabindex="-1">Project Highlights <a class="header-anchor" href="#project-highlights" aria-label="Permalink to “Project Highlights”">​</a></h2><h3 id="lightweight" tabindex="-1">Lightweight <a class="header-anchor" href="#lightweight" aria-label="Permalink to “Lightweight”">​</a></h3><ul><li>Focused core features</li><li>Clear code structure</li><li>Easy deployment configuration</li><li>Low resource consumption</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h3><ul><li>Go concurrency advantages</li><li>Multi-level caching</li><li>Query and indexing optimization</li><li>Static asset acceleration</li></ul><h3 id="extensibility" tabindex="-1">Extensibility <a class="header-anchor" href="#extensibility" aria-label="Permalink to “Extensibility”">​</a></h3><ul><li>Modular architecture</li><li>Theme and UI customization</li><li>API-level extension points</li><li>Feature-oriented modules</li></ul><h3 id="cross-platform" tabindex="-1">Cross-Platform <a class="header-anchor" href="#cross-platform" aria-label="Permalink to “Cross-Platform”">​</a></h3><ul><li>Multi-OS support</li><li>Prebuilt release packages and source builds</li><li>Cloud-friendly deployment</li><li>Mobile-ready UI</li></ul><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to “Roadmap”">​</a></h2><h3 id="version-plan" tabindex="-1">Version Plan <a class="header-anchor" href="#version-plan" aria-label="Permalink to “Version Plan”">​</a></h3><ul><li>v4.0: Core foundation improvements</li><li>v4.1: Performance and UX upgrades</li><li>v4.2: Feature expansion</li><li>v5.0: Larger architecture evolution</li></ul><h3 id="future-features" tabindex="-1">Future Features <a class="header-anchor" href="#future-features" aria-label="Permalink to “Future Features”">​</a></h3><ul><li>Better community onboarding</li><li>More third-party login providers</li><li>Stronger moderation and operation toolset</li><li>Advanced analytics and knowledge discovery</li></ul><h2 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to “Community”">​</a></h2><h3 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to “Feedback”">​</a></h3><ul><li>Community questions: <a href="https://github.com/mlogclub/bbs-go/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></li><li>Bugs and feature requests: <a href="https://github.com/mlogclub/bbs-go/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>Commercial licensing and support: <a href="./contact.html">Contact BBS-GO</a></li></ul><h2 id="license-and-commercial-use" tabindex="-1">License and Commercial Use <a class="header-anchor" href="#license-and-commercial-use" aria-label="Permalink to “License and Commercial Use”">​</a></h2><p>BBS-GO is open source under GPLv3. You may use, modify, and self-host it under the terms of GPLv3.</p><p>If you need to embed BBS-GO into a proprietary product, redistribute a modified version under a different license, or need custom commercial terms, see <a href="./license.html">License and Commercial Use</a>.</p><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to “About”">​</a></h2><p>BBS-GO is developed and maintained by the MlogClub team. If you have ideas or issues, feel free to reach out:</p><ul><li>Start a GitHub discussion</li><li>Submit a GitHub issue</li><li>Try the live demo community</li><li>Contact us for commercial licensing, deployment, or customization support</li></ul><div class="tip custom-block"><p class="custom-block-title">Support</p><p>If you need help:</p><ol><li>Read the docs: <a href="https://bbs-go.com" target="_blank" rel="noreferrer">https://bbs-go.com</a></li><li>Ask a question: <a href="https://github.com/mlogclub/bbs-go/discussions" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/discussions</a></li><li>Submit an issue: <a href="https://github.com/mlogclub/bbs-go/issues" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/issues</a></li></ol></div>',53)])])}const b=a(o,[["render",l]]);export{m as __pageData,b as default};
